package edu.pe.cibertec.saibm.libro.persistence;
import static org.assertj.core.api.Assertions.*; import java.util.UUID; import org.junit.jupiter.api.Test; import org.springframework.boot.test.autoconfigure.orm.jpa.DataJpaTest; import org.springframework.context.annotation.Import; import org.springframework.test.context.DynamicPropertyRegistry; import org.springframework.test.context.DynamicPropertySource; import org.testcontainers.junit.jupiter.*; import org.testcontainers.postgresql.PostgreSQLContainer; import edu.pe.cibertec.saibm.libro.application.port.out.BookRepositoryPort; import edu.pe.cibertec.saibm.libro.domain.model.Book; import edu.pe.cibertec.saibm.libro.infrastructure.out.persistence.BookPersistenceAdapter;
@DataJpaTest(properties="spring.jpa.hibernate.ddl-auto=validate") @Testcontainers @Import(BookPersistenceAdapter.class) class BookPersistenceAdapterTest { @Container static final PostgreSQLContainer POSTGRES=new PostgreSQLContainer("postgres:16.9-alpine"); @DynamicPropertySource static void db(DynamicPropertyRegistry r){r.add("spring.datasource.url",POSTGRES::getJdbcUrl);r.add("spring.datasource.username",POSTGRES::getUsername);r.add("spring.datasource.password",POSTGRES::getPassword);} @org.springframework.beans.factory.annotation.Autowired BookRepositoryPort books; @Test void flywayOwnsMetadataSchemaAndFiltersActive(){books.save(Book.create(UUID.randomUUID(),"Java Patterns","","Ada",""));books.save(Book.create(UUID.randomUUID(),"Hidden Java","","Alan","").deactivate());assertThat(books.search("java",0,10).content()).extracting(Book::title).containsExactly("Java Patterns");} }
